INSERT INTO products (id, brand_id, category_id, slug, name, summary, description, status, published_at) VALUES
    ('00000216-0000-4000-8000-000000000216', '00000200-0000-4000-8000-000000000200', '0000020d-0000-4000-8000-00000000020d', 'fernway-mountain-tea-seasons', '山茶十二月', '平裝本，288 頁，14.8×21 cm。', '林予安著，蕨徑出版。平裝，共 288 頁，開本 14.8×21 cm。', 'active', now()),
    ('0000021f-0000-4000-8000-00000000021f', '00000200-0000-4000-8000-000000000200', '0000020d-0000-4000-8000-00000000020d', 'fernway-city-sketch-walks', '城市速寫散步', '精裝本，192 頁，19×24 cm。', '陳以澄著，蕨徑出版。精裝，共 192 頁，開本 19×24 cm。', 'active', now()),
    ('00000227-0000-4000-8000-000000000227', '00000201-0000-4000-8000-000000000201', '0000020e-0000-4000-8000-00000000020e', 'paperwick-dot-notebook-a5', '紙芯 點格筆記本 A5', 'A5 點格筆記本，160 頁，內頁 5 mm 點格。', '160 頁，內頁為 100 g/m² 紙張，印 5 mm 點格。封面有霧灰、橄欖、磚紅三色，並附同色書籤帶。', 'active', now()),
    ('00000236-0000-4000-8000-000000000236', '00000201-0000-4000-8000-000000000201', '0000020e-0000-4000-8000-00000000020e', 'paperwick-gel-pen-set', '紙芯 中性筆 0.5 五色組', '0.5 mm 中性筆，黑、藍、紅、綠、灰各一支。', '一組五支，筆尖 0.5 mm，筆蓋顏色分別為黑、藍、紅、綠、灰。', 'active', now()),
    ('0000023c-0000-4000-8000-00000000023c', '00000202-0000-4000-8000-000000000202', '0000020f-0000-4000-8000-00000000020f', 'restwood-stoneware-mug', '棲木 石器馬克杯', '350 ml 石器馬克杯，可微波、可用洗碗機。', '容量 350 ml 的石器馬克杯，杯口一圈露胎。可放入微波爐與洗碗機。有燕麥、墨綠、霧灰三色。', 'active', now()),
    ('0000024b-0000-4000-8000-00000000024b', '00000202-0000-4000-8000-000000000202', '0000020f-0000-4000-8000-00000000020f', 'restwood-linen-tea-towel', '棲木 亞麻擦拭巾 2 入', '100% 亞麻擦拭巾，45×65 cm，2 入。', '一組兩條，每條 45×65 cm，材質為 100% 亞麻，附掛環。有燕麥、鼠尾草綠兩色。', 'active', now()),
    ('00000256-0000-4000-8000-000000000256', '00000202-0000-4000-8000-000000000202', '00000210-0000-4000-8000-000000000210', 'restwood-soy-candle-hinoki', '棲木 大豆蠟燭 檜木', '180 g 檜木香大豆蠟燭，燃燒約 40 小時。', '以大豆蠟製成，裝在琥珀色玻璃罐中，附木蓋。內容量 180 g，燃燒時間約 40 小時。', 'active', now()),
    ('0000025e-0000-4000-8000-00000000025e', '00000202-0000-4000-8000-000000000202', '00000210-0000-4000-8000-000000000210', 'restwood-reed-diffuser-white-tea', '棲木 擴香 白茶', '100 ml 白茶香擴香，附藤枝 6 支。', '透明玻璃瓶裝，內容量 100 ml，附藤枝 6 支。香味為白茶。', 'active', now()),
    ('00000264-0000-4000-8000-000000000264', '00000203-0000-4000-8000-000000000203', '00000211-0000-4000-8000-000000000211', 'saelo-hydrating-serum', '沙羅 保濕精華液', '30 ml 保濕精華液，茶色玻璃滴管瓶。', '容量 30 ml，裝在茶色玻璃滴管瓶中。洗臉後取適量塗抹於臉部。', 'active', now()),
    ('0000026a-0000-4000-8000-00000000026a', '00000203-0000-4000-8000-000000000203', '00000211-0000-4000-8000-000000000211', 'saelo-gel-cream', '沙羅 保濕凝霜', '50 ml 保濕凝霜，乳白霧面玻璃罐。', '容量 50 ml，裝在乳白霧面玻璃罐中。保養步驟的最後取適量塗抹於臉部。', 'active', now()),
    ('00000270-0000-4000-8000-000000000270', '00000203-0000-4000-8000-000000000203', '00000212-0000-4000-8000-000000000212', 'saelo-body-wash', '沙羅 沐浴露', '500 ml 沐浴露，按壓瓶裝。', '容量 500 ml，按壓瓶裝。取適量於濕潤的身體，搓出泡沫後沖洗。', 'active', now()),
    ('00000276-0000-4000-8000-000000000276', '00000203-0000-4000-8000-000000000203', '00000212-0000-4000-8000-000000000212', 'saelo-hand-cream', '沙羅 護手霜', '50 ml 護手霜，鋁管裝。', '容量 50 ml，鋁管裝。取適量塗抹於雙手。', 'active', now()),
    ('0000027c-0000-4000-8000-00000000027c', '00000204-0000-4000-8000-000000000204', '00000213-0000-4000-8000-000000000213', 'orili-cotton-tee', '織里 純棉圓領 T', '100% 棉圓領 T 恤，S 到 XL。', '100% 棉，圓領，領口為羅紋。尺寸有 S、M、L、XL，顏色有白、炭黑、燕麥。', 'active', now()),
    ('00000297-0000-4000-8000-000000000297', '00000204-0000-4000-8000-000000000204', '00000213-0000-4000-8000-000000000213', 'orili-oxford-shirt', '織里 牛津襯衫', '100% 棉牛津布襯衫，S 到 XL。', '100% 棉牛津布。尺寸有 S、M、L、XL，顏色有白、天空藍。', 'active', now()),
    ('000002ac-0000-4000-8000-0000000002ac', '00000204-0000-4000-8000-000000000204', '00000214-0000-4000-8000-000000000214', 'orili-canvas-tote', '織里 帆布托特包', '16 oz 帆布托特包，38×40×12 cm。', '16 oz 厚帆布，尺寸 38×40×12 cm，沒有印刷圖樣。有燕麥、墨綠兩色。', 'active', now()),
    ('000002b6-0000-4000-8000-0000000002b6', '00000204-0000-4000-8000-000000000204', '00000214-0000-4000-8000-000000000214', 'orili-bucket-hat', '織里 漁夫帽', '棉斜紋漁夫帽，頭圍 57–58 cm。', '棉斜紋布，帽簷車線。頭圍 57–58 cm。有卡其、黑兩色。', 'active', now()),
    ('000002c0-0000-4000-8000-0000000002c0', '00000205-0000-4000-8000-000000000205', '00000215-0000-4000-8000-000000000215', 'kumoleaf-high-mountain-oolong', '雲葉茶作 高山烏龍茶', '75 g 罐裝高山烏龍茶。', '圓筒馬口鐵罐裝，內容量 75 g。請存放於陰涼乾燥處。', 'active', now()),
    ('000002c6-0000-4000-8000-0000000002c6', '00000205-0000-4000-8000-000000000205', '00000215-0000-4000-8000-000000000215', 'kumoleaf-black-tea-bags', '雲葉茶作 紅茶茶包', '紅茶茶包，20 入。', '紙盒裝，內有 20 個紅茶茶包。請存放於陰涼乾燥處。', 'active', now()),
    ('000002cc-0000-4000-8000-0000000002cc', '00000206-0000-4000-8000-000000000206', '00000215-0000-4000-8000-000000000215', 'dawnroast-drip-coffee', '晨焙 濾掛咖啡', '濾掛咖啡，10 入。', '紙盒裝，內有 10 包濾掛咖啡。請存放於陰涼乾燥處。', 'active', now()),
    ('000002d2-0000-4000-8000-0000000002d2', '00000206-0000-4000-8000-000000000206', '00000215-0000-4000-8000-000000000215', 'dawnroast-coffee-beans', '晨焙 咖啡豆', '200 g 咖啡豆，可選中焙或深焙。', '牛皮紙袋裝，內容量 200 g，袋上有單向排氣閥。烘焙度可選中焙或深焙。請存放於陰涼乾燥處。', 'active', now());
