-- goen dev catalogue seed. Edited by hand; nothing generates it.
-- The seed/repair_*_faq.sql scripts rewrite specific FAQ answers on a database
-- that already has this catalogue, and their text must match the rows here.
-- Dev only. Loads as the owner. Idempotent-ish: run against a fresh schema.
BEGIN;


-- name_en is filled in for every one of these, because the header reads them and
-- the header is on every page. A category with no translation falls back to the
-- Chinese name, which is readable — but a dev catalogue that leaves half the
-- navigation untranslated makes the English site look broken when it is not.

-- Only technology is compared: its products state the same specifications, and a
-- sub-category inherits the department's answer.
UPDATE categories SET comparable = true WHERE slug = 'tech';

-- Each department's ground tone and header photograph; its sub-categories inherit both.
-- The key names a file in assets/media/products/, where image keys resolve.
UPDATE categories c
SET tone = d.tone, image_key = d.image_key, image_alt = d.image_alt, image_alt_en = d.image_alt_en
FROM (VALUES
    ('books-stationery', 'paper', 'department-books-stationery.webp', '疊起的書、筆記本與一支筆', 'Stacked books, a notebook and a pen'),
    ('home-living', 'stone', 'department-home-living.webp', '馬克杯、香氛蠟燭與亞麻布巾', 'Mugs, a scented candle and a linen cloth'),
    ('beauty', 'blush', 'department-beauty.webp', '精華液、乳霜、軟管與毛巾', 'A serum, a cream, a tube and a towel'),
    ('fashion', 'stone', 'department-fashion.webp', '帆布托特包、白 T 恤與漁夫帽', 'A canvas tote, a white t-shirt and a bucket hat'),
    ('food-drink', 'sage', 'department-food-drink.webp', '茶罐、茶碗、掛耳咖啡與茶匙', 'A tea tin, a tea bowl, a drip coffee bag and a spoon'),
    ('tech', 'mist', 'department-tech.webp', '筆電、耳罩式耳機、手機與充電線', 'A laptop, over-ear headphones, a phone and a cable')
) AS d(slug, tone, image_key, image_alt, image_alt_en)
WHERE c.slug = d.slug;


-- The general-merchandise departments' products. Copy is facts from the spec sheet, nothing the product does not state.

-- English copy for the seed's catalogue.
--
-- goen never invents a translation, but a dev
-- catalogue that leaves the products untranslated makes the English site look broken
-- when it is working exactly as designed. These are what a shop would type.
--
-- Only name and summary. The DESCRIPTION is the half somebody has to sit down and
-- write, and leaving it untranslated here is the honest demonstration of the
-- fallback: an English visitor reads an English name, an English summary and a
-- Chinese description, which is what a half-translated product looks like on
-- purpose.
UPDATE products p SET name_en = m.name_en, summary_en = m.summary_en
FROM (VALUES
    ('pixelight-9-pro', 'Pixelight 9 Pro 5G',
     'The flagship camera, a titanium frame and an LTPO display.'),
    ('pixelight-9', 'Pixelight 9 5G',
     'The flagship experience at a friendlier price.'),
    ('pixelight-9-pro-case', 'Pixelight 9 Pro Case',
     'Clear case with a military drop rating.'),
    ('aurora-edge-7', 'Aurora Edge 7',
     'Curved display, fast charging, a full day of battery.'),
    ('aurora-slate-11', 'Aurora Slate 11',
     'A light tablet with stylus support.'),
    ('aurora-charger-65', 'Aurora GaN 65W Charger',
     'Two-port GaN fast charging for phones and laptops alike.'),
    ('meridian-book-14', 'Meridian Book 14',
     'A 14-inch metal body, thin and light, with all-day battery.'),
    ('meridian-book-16-pro', 'Meridian Book 16 Pro',
     'A mobile workstation for people who make things.'),
    ('meridian-book-sleeve-14', 'Meridian Laptop Sleeve 14"',
     'Wool felt sleeve, scratch and splash resistant.'),
    ('meridian-watch-s3', 'Meridian Watch S3',
     'A smartwatch that measures your health around the clock.'),
    ('koto-over-ear', 'Koto Over-Ear Quiet',
