-- Warranty terms, per product and deliberately not all the same.
--
-- This is the whole reason products.warranty_months is a column rather than a
-- site-wide setting: a phone and a braided cable do not carry the same cover.
-- Registration is REFUSED while it is NULL, so every product no one has stated a
-- term for is left unset on purpose — an untouched shop that has not thought about
-- warranties should see the honest refusal, not a term goen invented.
UPDATE products p SET warranty_months = m.months
FROM (VALUES
    ('pixelight-9-pro', 24), ('pixelight-9', 24), ('aurora-edge-7', 24),
    ('aurora-slate-11', 24), ('koto-pad-mini', 24),
    ('meridian-book-14', 24), ('meridian-book-16-pro', 36),
    ('meridian-watch-s3', 24), ('nimbus-band-2', 12),
    ('koto-over-ear', 12), ('nimbus-buds-pro', 12),
    ('aurora-charger-65', 12), ('koto-cable-braided', 6)
) AS m(slug, months)
WHERE p.slug = m.slug;



-- English labels for the seed's option axes and their values.
--
-- These are LABELS. The variant picker puts the choice in the URL and the URL
-- carries the canonical Chinese value, so translating 星霧藍 changes what a visitor
-- READS and never what a link SELECTS — which is why display and identity are two
-- columns. Numeric values (256GB) need no translation and get none: the read falls
-- back, and a NULL means "same in both languages" exactly as it means "not done
-- yet".
UPDATE product_options SET name_en = 'Colour' WHERE name = '顏色';
UPDATE product_options SET name_en = 'Capacity' WHERE name = '容量';
UPDATE product_options SET name_en = 'Size' WHERE name = '尺寸';
UPDATE product_options SET name_en = 'Roast' WHERE name = '烘焙度';

UPDATE product_option_values v SET value_en = m.en
FROM (VALUES
    ('星霧藍', 'Mist Blue'), ('曜石黑', 'Obsidian Black'), ('曙光金', 'Dawn Gold'),
    ('午夜灰', 'Midnight Grey'), ('天空藍', 'Sky Blue'), ('太空銀', 'Space Silver'),
    ('櫻花粉', 'Sakura Pink'), ('玫瑰金', 'Rose Gold'), ('珊瑚橘', 'Coral Orange'),
    ('薄荷綠', 'Mint Green'), ('墨綠', 'Ink Green'), ('石墨灰', 'Graphite Grey'),
    ('石墨黑', 'Graphite Black'), ('炭黑', 'Charcoal'), ('雲白', 'Cloud White'),
    ('燕麥', 'Oat'), ('胡桃', 'Walnut'), ('透明', 'Clear'), ('霧透', 'Frosted'),
    ('銀', 'Silver'), ('黑', 'Black'),
    ('白', 'White'), ('霧灰', 'Fog Grey'), ('鼠尾草綠', 'Sage'), ('卡其', 'Khaki'), ('橄欖', 'Olive'), ('磚紅', 'Brick'), ('中焙', 'Medium'), ('深焙', 'Dark')
) AS m(zh, en)
WHERE v.value = m.zh;

-- The colour each name shows as on a product page. Read from the shop's own
-- colour names rather than sampled from a photograph. Whoever holds the real
-- products should correct any that do not match one.
--
-- 透明 and 霧透 are absent on purpose: they are finishes, not colours, and a
-- flat fill would show them as two shades of grey that neither of them is. The
-- page falls back to their names, which is what it already did for capacities.
UPDATE product_option_values v SET swatch_hex = m.hex
FROM (VALUES
    ('雲白', '#f4f5f6'), ('太空銀', '#d9dadb'), ('銀', '#c9ccce'),
    ('燕麥', '#e3dbcb'), ('曙光金', '#e8c9a0'), ('玫瑰金', '#e0bfb8'),
    ('櫻花粉', '#f2c9d4'), ('珊瑚橘', '#f08163'), ('薄荷綠', '#b7e2cd'),
    ('天空藍', '#a8c8e8'), ('星霧藍', '#9fb3c8'), ('墨綠', '#2f4f43'),
    ('胡桃', '#7b5b43'), ('石墨灰', '#6e7276'), ('午夜灰', '#3c4043'),
    ('炭黑', '#36393d'), ('石墨黑', '#2b2d30'), ('曜石黑', '#1c1c1e'),
    ('黑', '#16181a'),
    ('白', '#f7f7f5'), ('霧灰', '#c8c9c7'), ('鼠尾草綠', '#a7b59d'), ('卡其', '#c2b28f'), ('橄欖', '#6b6f4a'), ('磚紅', '#a5523a')
) AS m(zh, hex)
WHERE v.value = m.zh;


-- Stock arrives through the LEDGER, not through the column.
--
-- record_inventory_movement is the only writer of product_variants.stock_quantity —
-- that is what makes "one writer" true rather than aspirational — and this seed used
-- to set the column directly, because it runs as the owner and the owner is subject
-- to no REVOKE. The cost showed up the day /admin/stock/{sku} started reading the
-- ledger: a variant held 19 units and its history explained 7 of them.
--
-- A fixture that reaches past the application is a fixture for a claim nobody is
-- testing. This one goes through the same door a shop's first delivery does.
-- Only the ones that HAVE stock. A variant seeded at zero is deliberately sold out —
-- the restock notice needs one — and a movement of zero is refused by
-- inventory_movements_delta_non_zero, correctly: nothing happened.
SELECT record_inventory_movement(v.id, m.qty, 'receipt', 'seed:' || v.sku, 'admin')
