-- English for the seed's spec table, as ONE mapping rather than two more columns in
-- eighty INSERT rows: the vocabulary is 22 labels and this is where a reader can
-- see all of them at once.
--
-- Only the labels and the values that contain Chinese. '5000mAh' and '80W' are the
-- same in both languages, and a NULL there means "no translation needed" exactly as
-- it means "not translated yet" — the read falls back either way, which is why the
-- column does not try to tell those apart.
UPDATE product_specs s SET label_en = m.en
FROM (VALUES
    ('螢幕', 'Screen'), ('處理器', 'Processor'), ('相機', 'Camera'),
    ('電池', 'Battery'), ('快充', 'Fast charging'), ('顯示卡', 'Graphics'),
    ('重量', 'Weight'), ('尺寸', 'Size'), ('材質', 'Material'),
    ('續航', 'Battery life'), ('降噪', 'Noise cancelling'), ('單體', 'Driver'),
    ('連線', 'Connectivity'), ('防水', 'Water resistance'), ('防摔', 'Drop rating'),
    ('感測', 'Sensors'), ('手寫筆', 'Stylus'), ('功率', 'Power'),
    ('輸出', 'Output'), ('孔位', 'Ports'), ('長度', 'Length'), ('體積', 'Volume'),
    ('作者', 'Author'),
    ('出版社', 'Publisher'),
    ('頁數', 'Pages'),
    ('裝訂', 'Binding'),
    ('紙張', 'Paper'),
    ('格線', 'Grid'),
    ('筆尖', 'Tip'),
    ('顏色', 'Inks'),
    ('內容量', 'Contents'),
    ('微波爐', 'Microwave'),
    ('洗碗機', 'Dishwasher'),
    ('燃燒時間', 'Burn time'),
    ('香味', 'Scent'),
    ('藤枝', 'Reeds'),
    ('使用方式', 'Directions'),
    ('保存期限', 'Shelf life'),
